<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { usePlanStore } from '../stores/planStore'
import { useRunStore } from '../stores/runStore'
import { api, errorMessage } from '../api'
import { CanvasAdapter } from '../adapter/CanvasAdapter'
import { NODE_TYPES, NODE_TYPE_COLORS, NODE_TYPE_LABELS } from '../../../shared/constants.js'
import { createNode, taskSpecToPlan } from '../../../shared/plan.js'
import { validatePlanSchema } from '../../../shared/schema.js'
import { LOGIN_SPEC } from '../../../shared/example.js'
import type { NodeType, Plan, ValidationIssue } from '../types'
import AppIcon from '../components/AppIcon.vue'
import DecomposeDialog from '../components/DecomposeDialog.vue'
import PropertyPanel from '../components/PropertyPanel.vue'
import LogPanel from '../components/LogPanel.vue'
const store=usePlanStore(),run=useRunStore()
const canvas=ref<HTMLElement>(), jsonFile=ref<HTMLInputElement>()
const decomposeOpen=ref(false),plansOpen=ref(false),helpOpen=ref(false)
const leftCollapsed=ref(false),rightCollapsed=ref(false),logsCollapsed=ref(false)
const zoom=ref(100),saving=ref(false),loadingExample=ref(false),listBusy=ref(false),list=ref<any[]>([])
const dragging=ref(false)
let adapter:CanvasAdapter|undefined
let copied:ReturnType<CanvasAdapter['copySelection']>|undefined
const planName=computed({get:()=>store.plan.name,set:(value:string)=>store.mutate(p=>{p.name=value})})
const stateLabels:Record<string,string>={IDLE:'尚未运行',VALIDATING:'正在校验',RUNNING:'运行中',SUCCESS:'执行成功',FAILED:'执行失败',CANCELED:'已停止'}
const nodeHints:Record<string,string>={start:'流程唯一入口',task:'执行一个模拟任务',condition:'true / false 条件路由',delay:'等待指定时长',end:'汇合并结束流程'}
watch(()=>store.plan,(p)=>adapter?.render(p),{deep:true})
watch(()=>store.selectedId,id=>adapter?.select(id))
watch(()=>run.nodeStates,s=>adapter?.setStates(s),{deep:true})
watch(()=>run.active,value=>adapter?.setLocked(value))
watch(()=>store.issues,issues=>{adapter?.setIssues(issues);if(issues.length)rightCollapsed.value=false},{deep:true})
watch(()=>run.status,(value,old)=>{if(old==='RUNNING'&&value==='SUCCESS')ElMessage.success('编排执行完成');if(old==='RUNNING'&&value==='FAILED')ElMessage.error('执行失败，请查看日志与节点状态')})
async function safe(action:()=>any){try{await action()}catch(e){ElMessage.error(errorMessage(e))}}
async function save(){saving.value=true;try{await store.save();ElMessage.success('方案已保存到本地服务')}catch(e){ElMessage.error(errorMessage(e))}finally{saving.value=false}}
async function loadExample(){if(run.active)return;loadingExample.value=true;try{const {data}=await api.post('/decompose',{text:LOGIN_SPEC,format:'auto'});generated(taskSpecToPlan(data.taskSpec) as Plan)}catch(e){ElMessage.error(errorMessage(e))}finally{loadingExample.value=false}}
function generated(plan:Plan){run.reset();store.replace(plan);nextTick(()=>{adapter?.fit();ElMessage.success(`已生成 ${plan.nodes.length} 个节点、${plan.edges.length} 条连线`)})}
async function start(){await safe(()=>run.start());if(store.issues.length){const first=store.issues.find(i=>i.nodeId);if(first?.nodeId)adapter?.focus(first.nodeId)}}
async function newPlan(){if(run.active)return;if(store.dirty&&store.nodes.length){try{await ElMessageBox.confirm('当前编排尚未保存，确定新建空白方案？','新建方案',{confirmButtonText:'新建',cancelButtonText:'取消'})}catch{return}}run.reset();store.reset()}
async function openPlans(){plansOpen.value=true;listBusy.value=true;try{const {data}=await api.get('/plans');list.value=Array.isArray(data)?data:data.plans || []}catch(e){ElMessage.error(errorMessage(e))}finally{listBusy.value=false}}
async function load(id:string){await safe(async()=>{await store.load(id);run.reset();await run.restore();plansOpen.value=false;await nextTick();adapter?.fit();ElMessage.success('方案已打开')})}
async function removePlan(id:string){try{await ElMessageBox.confirm('删除后将无法从方案列表恢复。已导出的 JSON 文件不受影响。','删除方案',{confirmButtonText:'删除',cancelButtonText:'取消',type:'warning'});await api.delete(`/plans/${encodeURIComponent(id)}`);list.value=list.value.filter(p=>p.id!==id);ElMessage.success('方案已删除')}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(errorMessage(e))}}
async function importJson(e:Event){const target=e.target as HTMLInputElement,file=target.files?.[0];target.value='';if(!file)return;if(file.size>2*1024*1024){ElMessage.error('方案文件过大，请选择 2 MB 以内的 JSON');return}await safe(async()=>{let value;try{value=JSON.parse(await file.text())}catch{throw new Error('JSON 文件无法解析，请检查文件是否损坏')}await store.importPlan(value);run.reset();await nextTick();adapter?.fit();ElMessage.success('方案已导入并保存')})}
function dragStart(event:DragEvent,type:string){if(run.active){event.preventDefault();return}event.dataTransfer?.setData('application/vto-node',type);if(event.dataTransfer)event.dataTransfer.effectAllowed='copy';dragging.value=true}
function drop(event:DragEvent){dragging.value=false;if(run.active)return;const type=event.dataTransfer?.getData('application/vto-node') as NodeType;if(!NODE_TYPES.includes(type))return;const p=adapter?.toLocal(event.clientX,event.clientY);if(p)addNode(type,Math.round((p.x-72)/20)*20,Math.round((p.y-32)/20)*20)}
function addNode(type:NodeType,x?:number,y?:number){if(run.active)return;if(store.nodes.length>=100){ElMessage.error('每个方案最多 100 个节点');return}if(['start','end'].includes(type)&&store.nodes.some(n=>n.type===type)){ElMessage.warning(`${NODE_TYPE_LABELS[type]}节点只能有一个`);return}const node=createNode(type,x??80+(store.nodes.length%3)*160,y??80+Math.floor(store.nodes.length/3)*120);store.mutate(p=>p.nodes.push(node));store.selectedId=node.id}
function autoLayout(){safe(async()=>{store.autoLayout();await nextTick();adapter?.fit()})}
function validate(){const p=store.plan,issues:ValidationIssue[]=[...validatePlanSchema(p)];for(const type of ['start','end']){if(p.nodes.filter(n=>n.type===type).length!==1)issues.push({rule:'R1',message:`方案需要且只能有一个${type==='start'?'开始':'结束'}节点`})}for(const n of p.nodes){if(n.type!=='start'&&!p.edges.some(e=>e.target===n.id))issues.push({nodeId:n.id,rule:'R3',message:'节点没有前置连接'});if(n.type!=='end'&&!p.edges.some(e=>e.source===n.id))issues.push({nodeId:n.id,rule:'R3',message:'节点尚未连接后续流程'});if(n.type==='condition'&&p.edges.filter(e=>e.source===n.id).length!==2)issues.push({nodeId:n.id,rule:'R4',message:'条件节点需连接 true 和 false 两个分支'})}store.issues=issues;ElMessage({type:issues.length?'warning':'success',message:issues.length?`发现 ${issues.length} 个问题，请查看属性面板`:'基础检查通过；执行时服务端将完成全量校验'})}
function keydown(e:KeyboardEvent){const target=e.target as HTMLElement;if(target.closest('input,textarea,[contenteditable="true"],.el-dialog'))return;const mod=e.metaKey||e.ctrlKey;if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();save();return}if(run.active)return;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?store.redo():store.undo()}else if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();store.redo()}else if(mod&&e.key.toLowerCase()==='c'){e.preventDefault();copied=adapter?.copySelection();if(copied?.nodes.length)ElMessage.success(`已复制 ${copied.nodes.length} 个节点`)}else if(mod&&e.key.toLowerCase()==='v'){e.preventDefault();if(copied)adapter?.paste(copied)}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();adapter?.deleteSelected()}else if(e.key==='Escape'){store.selectedId=''}else if(e.key.toLowerCase()==='f'){adapter?.fit()}}
function flushDraft(){store.writeDraft()}
onMounted(async()=>{const restored=store.restoreDraft();if(canvas.value)adapter=new CanvasAdapter(canvas.value,store.plan,{changed:p=>store.commit(p),selected:id=>{store.selectedId=id},notify:message=>ElMessage.warning(message),zoom:value=>{zoom.value=value}});if(restored&&store.nodes.length){adapter?.fit();ElMessage.info('已恢复上次的编排草稿')}await run.restore();adapter?.setLocked(run.active);adapter?.setStates(run.nodeStates);window.addEventListener('keydown',keydown);window.addEventListener('beforeunload',flushDraft)})
onBeforeUnmount(()=>{store.writeDraft();run.dispose();adapter?.dispose();window.removeEventListener('keydown',keydown);window.removeEventListener('beforeunload',flushDraft)})
</script>
<template><div class="editor-shell">
 <header class="topbar"><div class="brand"><div class="brand-mark"><span></span><span></span><span></span></div><div><b>VTO<span>STUDIO</span></b><small>可视化任务编排器</small></div></div><div class="top-divider"></div><div class="document-title"><input v-model="planName" maxlength="50" :disabled="run.active" aria-label="方案名称"/><span class="save-indicator"><i :class="{dirty:store.dirty}"></i>{{store.dirty?'有未保存的更改':store.savedAt?'所有更改已保存':'本地工作区'}}</span></div><div class="top-actions"><el-button @click="openPlans" :disabled="run.active"><AppIcon name="folder" :size="16"/><span>方案</span></el-button><el-button @click="save" :loading="saving" :disabled="run.active"><AppIcon name="save" :size="16"/><span>保存</span></el-button><span class="action-divider"></span><el-button type="primary" plain @click="decomposeOpen=true" :disabled="run.active"><AppIcon name="spark" :size="16"/>导入规格</el-button><el-button v-if="!run.active" type="primary" class="execute-button" :disabled="!store.nodes.length" @click="start"><AppIcon name="play" :size="16"/>执行编排</el-button><el-button v-else type="danger" @click="safe(()=>run.stop())"><AppIcon name="stop" :size="16"/>停止执行</el-button><button class="icon-button help-button" title="使用帮助" @click="helpOpen=true"><AppIcon name="help"/></button></div></header>
 <div class="workspace">
  <aside v-if="!leftCollapsed" class="node-library side-panel"><div class="panel-heading"><span>节点库 <b>5</b></span><button class="icon-button rotate-180" title="收起节点库" @click="leftCollapsed=true"><AppIcon name="chevron" :size="15"/></button></div><p class="panel-description">拖入画布，连接你的想法</p><div class="node-list"><button v-for="type in NODE_TYPES" :key="type" class="library-node" :draggable="!run.active" :disabled="run.active" @dragstart="dragStart($event,type)" @dragend="dragging=false" @dblclick="addNode(type as NodeType)" :title="`拖拽或双击添加${NODE_TYPE_LABELS[type as NodeType]}`"><div class="node-icon" :style="{color:NODE_TYPE_COLORS[type as NodeType],background:NODE_TYPE_COLORS[type as NodeType]+'12'}"><AppIcon :name="type" :size="19"/></div><div><strong>{{NODE_TYPE_LABELS[type as NodeType]}}</strong><small>{{nodeHints[type]}}</small></div><AppIcon name="grip" :size="15"/></button></div><div class="library-note"><div class="tiny-label">从一个好例子开始</div><h4>用户登录流程</h4><p>并行校验、身份认证、<br/>条件分支与结果汇合。</p><button @click="loadExample" :disabled="run.active||loadingExample">载入示例 <span>↗</span></button></div><div class="library-footer"><AppIcon name="info" :size="14"/>20 px 网格吸附已开启</div></aside>
  <div class="center-pane"><div class="canvas-toolbar"><div class="canvas-tools"><button v-if="leftCollapsed" class="icon-button" title="展开节点库" @click="leftCollapsed=false"><AppIcon name="layout" :size="17"/></button><span class="canvas-tab"><i></i>编排画布</span><span class="node-count">{{store.nodes.length}} 节点 <span>·</span> {{store.edges.length}} 连线</span></div><div class="canvas-tools"><button class="icon-button" :disabled="run.active||!store.past.length" title="撤销 ⌘/Ctrl Z" @click="store.undo"><AppIcon name="undo" :size="17"/></button><button class="icon-button" :disabled="run.active||!store.future.length" title="重做 ⌘/Ctrl Shift Z" @click="store.redo"><AppIcon name="redo" :size="17"/></button><span class="toolbar-separator"></span><button class="text-tool" :disabled="run.active||!store.nodes.length" @click="autoLayout"><AppIcon name="layout" :size="15"/>自动布局</button><button class="text-tool" :disabled="run.active||!store.nodes.length" @click="validate"><AppIcon name="check" :size="15"/>检查</button><button v-if="rightCollapsed" class="icon-button" title="展开属性面板" @click="rightCollapsed=false"><AppIcon name="chevron" :size="16"/></button></div></div>
   <div class="canvas-area" :class="{'is-dragging':dragging}" @dragover.prevent @drop.prevent="drop"><div ref="canvas" class="graph-container"></div><div v-if="!store.nodes.length" class="empty-canvas"><div class="empty-illustration"><div class="empty-mini-node a"><AppIcon name="start" :size="19"/></div><div class="empty-link one"></div><div class="empty-mini-node b"><AppIcon name="task" :size="21"/></div><div class="empty-link two"></div><div class="empty-mini-node c"><AppIcon name="condition" :size="20"/></div></div><span class="eyebrow">YOUR NEXT WORKFLOW STARTS HERE</span><h1>把想法，编排成行动。</h1><p>导入设计规格，自动拆解任务与依赖。<br/>也可以从左侧拖入节点，搭建你的第一条流程。</p><div><el-button type="primary" @click="decomposeOpen=true"><AppIcon name="plus" :size="17"/>从规格创建</el-button><el-button @click="loadExample" :loading="loadingExample">载入示例<AppIcon name="chevron" :size="14"/></el-button></div><small>自动分解 · 可视化编排 · 本地模拟执行</small></div><div v-if="dragging" class="drop-hint"><AppIcon name="plus" :size="16"/>释放以添加节点 · 自动吸附 20px 网格</div><div v-if="store.nodes.length" class="canvas-run-badge" :class="run.status.toLowerCase()"><i></i>{{stateLabels[run.status]}}<span v-if="run.active">{{run.progress}}%</span></div><div class="canvas-bottom-hint"><span>Shift 拖动框选</span><i>·</i><span>右键拖动画布</span><i>·</i><span>⌘ / Ctrl + 滚轮缩放</span></div><div class="zoom-controls"><button title="缩小" @click="adapter?.zoom(-.1)"><AppIcon name="minus" :size="15"/></button><span>{{zoom}}%</span><button title="放大" @click="adapter?.zoom(.1)"><AppIcon name="plus" :size="15"/></button><i></i><button title="适应画布 F" @click="adapter?.fit()"><AppIcon name="fit" :size="16"/></button></div></div>
   <LogPanel :collapsed="logsCollapsed" @toggle="logsCollapsed=!logsCollapsed" @focus="adapter?.focus($event)"/>
  </div>
  <PropertyPanel v-if="!rightCollapsed" @collapse="rightCollapsed=true" @focus="adapter?.focus($event)" @remove="adapter?.deleteSelected()"/>
 </div>
 <DecomposeDialog v-model="decomposeOpen" @generated="generated"/>
 <el-dialog v-model="plansOpen" title="我的编排方案" width="720px" class="plans-dialog"><template #header><div class="dialog-kicker">LOCAL WORKSPACE</div><h2>我的编排方案</h2><p class="dialog-description">保存在这台电脑上的流程，随时继续。</p></template><div class="plan-list-actions"><el-button type="primary" plain @click="plansOpen=false;newPlan()"><AppIcon name="plus" :size="15"/>新建方案</el-button><el-button @click="jsonFile?.click()"><AppIcon name="upload" :size="15"/>导入 JSON</el-button><el-button :disabled="!store.nodes.length" @click="store.exportPlan()"><AppIcon name="download" :size="15"/>导出当前方案</el-button></div><div v-loading="listBusy" class="plan-list"><el-empty v-if="!list.length&&!listBusy" description="还没有保存的方案" :image-size="80"/><div v-for="plan in list" :key="plan.id" class="saved-plan"><div class="saved-plan-icon"><AppIcon name="layout" :size="21"/></div><div class="saved-plan-title"><h4>{{plan.name}}</h4><span>更新于 {{new Date(plan.updatedAt).toLocaleString('zh-CN')}} · v{{plan.version}}</span></div><el-button size="small" @click="load(plan.id)">打开</el-button><button class="icon-button danger-hover" :aria-label="`删除方案 ${plan.name}`" @click="removePlan(plan.id)"><AppIcon name="trash" :size="16"/></button></div></div></el-dialog>
 <el-dialog v-model="helpOpen" title="开始你的第一条编排" width="600px"><div class="help-steps"><p><b>01</b><span>点击「导入规格」，粘贴 Markdown 或编号文本，确认清单。</span></p><p><b>02</b><span>拖拽节点，连接右侧出端口与左侧入端口；右侧面板修改属性。</span></p><p><b>03</b><span>点击「执行编排」，观察并行、条件路由、重试和日志。</span></p><p><b>04</b><span>保存方案，或在方案列表导入、导出 JSON。</span></p></div><div class="shortcut-grid"><span>保存 <kbd>⌘ / Ctrl S</kbd></span><span>撤销 <kbd>⌘ / Ctrl Z</kbd></span><span>复制 / 粘贴 <kbd>⌘ / Ctrl C / V</kbd></span><span>删除 <kbd>Delete</kbd></span><span>框选 <kbd>Shift + 拖动</kbd></span><span>适应画布 <kbd>F</kbd></span></div><p class="field-help">任务仅作本地模拟执行，不运行外部脚本。依赖安装完成后，整个流程可以断网演示。</p></el-dialog>
 <input ref="jsonFile" type="file" accept=".json,application/json" hidden @change="importJson"/>
</div></template>
